<script lang="ts">
	import type { Snippet } from "svelte";
	import { BROWSER } from "esm-env";
	import UIContent from "./UIContent.svelte";

	/**
	 * @description
	 * A base popover component using the native Popover API and CSS Anchor Positioning.
	 * Use as a foundation for dropdowns, tooltips, contextual help, etc.
	 * Supports trigger snippets, external anchors, placement with fallbacks, and light dismiss.
	 * @cssprop --popover-background - Background color. (Default: var(--surface-background))
	 * @cssprop --popover-border - Border shorthand. (Default: var(--surface-border))
	 * @cssprop --popover-border-radius - Border radius. (Default: var(--surface-border-radius))
	 * @cssprop --popover-shadow - Box shadow. (Default: var(--surface-shadow))
	 * @cssprop --popover-width - Width of the popover. (Default: max-content)
	 * @cssprop --popover-max-width - Maximum width. (Default: calc(100vw - 2rem))
	 * @cssprop --popover-max-height - Maximum height. (Default: calc(100vh - 2rem))
	 * @example
	 * <Popover placement="bottom-start">
	 *     {#snippet trigger({ toggle, triggerAttrs })}
	 *         <button {...triggerAttrs}>Open</button>
	 *     {/snippet}
	 *     <p>Popover content</p>
	 * </Popover>
	 */
	let {
		open = $bindable(false),
		anchor,
		placement = "bottom-start",
		fallbacks = ["flip-block", "flip-inline"],
		visibility = "anchors-visible",
		mode = "auto",
		offset = "0.25rem",
		width,
		maxWidth,
		maxHeight,
		unstyled = false,
		trigger,
		children,
		class: className = "",
		onopen,
		onclose,
	}: {
		/** Whether the popover is open (bindable) */
		open?: boolean;
		/** Element to anchor to (if no trigger snippet provided) */
		anchor?: HTMLElement | string;
		/** Placement relative to anchor */
		placement?: "bottom-start" | "bottom" | "bottom-end" | "top-start" | "top" | "top-end";
		/** CSS position-try-fallbacks values */
		fallbacks?: string[];
		/** CSS position-visibility value */
		visibility?: "always" | "anchors-visible" | "no-overflow";
		/** Popover mode: "auto" (light dismiss) or "manual" */
		mode?: "auto" | "manual";
		/** Gap between anchor and popover (CSS length value) */
		offset?: string;
		/** Width of the popover */
		width?: string;
		/** Max width of the popover */
		maxWidth?: string;
		/** Max height of the popover */
		maxHeight?: string;
		/** Remove default styling (background, border, shadow) */
		unstyled?: boolean;
		/** Optional trigger snippet */
		trigger?: Snippet<[{ 
			toggle: () => void;
			isOpen: boolean;
			triggerAttrs: Record<string, string>;
		}]>;
		/** Popover content */
		children: Snippet;
		/** Additional CSS class */
		class?: string;
		/** Called when popover opens */
		onopen?: () => void;
		/** Called when popover closes */
		onclose?: () => void;
	} = $props();

	const id = crypto.randomUUID();
	const anchorName = `--anchor-${id}`;
	
	let popoverEl: HTMLDivElement | null = $state(null);

	// Handle external anchor (not using trigger snippet)
	$effect(() => {
		if (!BROWSER || trigger) return; // Skip if using trigger snippet
		
		let anchorEl: HTMLElement | null = null;
		
		if (typeof anchor === "string") {
			anchorEl = document.querySelector(anchor);
		} else if (anchor instanceof HTMLElement) {
			anchorEl = anchor;
		}

		if (anchorEl) {
			anchorEl.style.setProperty("anchor-name", anchorName);
		}
	});

	// Sync open state with popover
	$effect(() => {
		if (!BROWSER || !popoverEl) return;

		if (open) {
			if (!popoverEl.matches(":popover-open")) {
				popoverEl.showPopover();
			}
		} else {
			if (popoverEl.matches(":popover-open")) {
				popoverEl.hidePopover();
			}
		}
	});

	// Listen for toggle events
	$effect(() => {
		if (!BROWSER || !popoverEl) return;

		const handleToggle = (e: ToggleEvent) => {
			const isOpen = e.newState === "open";
			if (isOpen !== open) {
				open = isOpen;
				if (isOpen) {
					onopen?.();
				} else {
					onclose?.();
				}
			}
		};

		popoverEl.addEventListener("toggle", handleToggle as EventListener);
		return () => popoverEl?.removeEventListener("toggle", handleToggle as EventListener);
	});

	function toggle() {
		if (!popoverEl) return;
		
		if (popoverEl.matches(":popover-open")) {
			popoverEl.hidePopover();
		} else {
			popoverEl.showPopover();
		}
	}

	// Attrs to spread on trigger element
	const triggerAttrs = $derived({
		popovertarget: id,
		"aria-haspopup": "true",
		"aria-expanded": String(open),
		"aria-controls": id,
		style: `anchor-name: ${anchorName}`,
	});

	// Build positioning styles using anchor() functions for precise edge alignment
	const popoverStyle = $derived.by(() => {
		const styles: string[] = [
			`position-anchor: ${anchorName}`,
		];
		
		// Vertical: top or bottom edge alignment
		if (placement.startsWith("top")) {
			styles.push(`bottom: anchor(top)`);
			styles.push(`margin-bottom: ${offset}`);
		} else {
			styles.push(`top: anchor(bottom)`);
			styles.push(`margin-top: ${offset}`);
		}
		
		// Horizontal: edge alignment
		if (placement.endsWith("-start")) {
			styles.push(`left: anchor(left)`);
		} else if (placement.endsWith("-end")) {
			styles.push(`right: anchor(right)`);
		} else {
			// Center
			styles.push(`left: anchor(center)`);
			styles.push(`translate: -50% 0`);
		}
		
		// Viewport constraint and fallbacks
		styles.push(`position-visibility: ${visibility}`);
		if (fallbacks.length) {
			styles.push(`position-try-fallbacks: ${fallbacks.join(", ")}`);
		}
		
		// Sizing
		if (width) styles.push(`--popover-width: ${width}`);
		if (maxWidth) styles.push(`--popover-max-width: ${maxWidth}`);
		if (maxHeight) styles.push(`--popover-max-height: ${maxHeight}`);
		
		return styles.join("; ");
	});
</script>

{#if trigger}
	{@render trigger({ toggle, isOpen: open, triggerAttrs })}
{/if}

<div
	bind:this={popoverEl}
	{id}
	popover={mode}
	class="Popover {className}"
	class:unstyled
	style={popoverStyle}
>
	<UIContent>
		{@render children()}
	</UIContent>
</div>

<style>
	.Popover {
		position: fixed;
		inset: auto;
		margin: 0;
		padding: 0;
		background: var(--popover-background, var(--surface-background));
		border: var(--popover-border, var(--surface-border));
		border-radius: var(--popover-border-radius, var(--surface-border-radius));
		box-shadow: var(--popover-shadow, var(--surface-shadow));
		width: var(--popover-width, max-content);
		max-width: var(--popover-max-width, calc(100vw - 2rem));
		max-height: var(--popover-max-height, calc(100vh - 2rem));
		overflow: auto;
	}

	.Popover.unstyled {
		background: transparent;
		border: none;
		border-radius: 0;
		box-shadow: none;
	}

	.Popover:popover-open {
		opacity: 1;
		translate: 0 0;
		transition:
			opacity var(--transition-duration-fast) ease-out,
			translate var(--transition-duration-fast) ease-out,
			display var(--transition-duration-fast) allow-discrete;
	}

	.Popover:not(:popover-open) {
		opacity: 0;
		translate: 0 calc(-1 * var(--space-xxs));
		transition:
			opacity var(--transition-duration-fast) ease-in,
			translate var(--transition-duration-fast) ease-in,
			display var(--transition-duration-fast) allow-discrete;
	}

	@starting-style {
		.Popover:popover-open {
			opacity: 0;
			translate: 0 calc(-1 * var(--space-xxs));
		}
	}

	@media (prefers-reduced-motion: reduce) {
		.Popover:popover-open,
		.Popover:not(:popover-open) {
			transition: none;
		}
	}
</style>
